-- ------------------------------------------------------------
--  마스터 FK 연결
-- ------------------------------------------------------------
update legacy_settlements l set retailer_id = r.id
  from retailers r where r.code = l.retailer_code and l.retailer_id is null;
update legacy_settlements l set workshop_id = w.id
  from workshops w where w.code = l.workshop_code and l.workshop_id is null;

-- ------------------------------------------------------------
--  포털의 실제 Pick up & Delivery 정산유형 코드로 맞춘다.
--  (화면은 legacy.type_code 를 settlement_types.source_config->>'preset' 또는
--   settlement_types.code 와 매칭한다. 아래 update 가 1행 이상 바꾸면 연결 완료,
--   0행이면 유형을 못 찾은 것이고 화면에는 "(수동 업로드분)" 으로 따로 보인다.)
-- ------------------------------------------------------------
update legacy_settlements l
   set type_code = t.code
  from settlement_types t
 where l.item = 'PND'
   and (t.name ilike '%pick%' or t.code ilike '%pick%'
        or t.name ilike '%딜리버리%' or t.name ilike '%delivery%');

-- 어떤 유형에 붙었는지 확인
select distinct l.type_code, t.name, t.direction, t.period
  from legacy_settlements l
  left join settlement_types t on t.code = l.type_code
 where l.item = 'PND';

-- ------------------------------------------------------------
--  검증 — 아래 분기 합계가 실제 바우처 공급가액과 같아야 한다
--    FY26 Q1 152,866,000 / Q2 188,148,842 / Q3 189,431,500 / Q4 209,085,750
--    FY27 Q1 213,482,075
-- ------------------------------------------------------------
select period_key, period_label, count(*) as 지점수,
       sum(amount) as 공급가액,
       sum(amount) * 0.1 as 부가세_10pct,
       sum((detail->>'trips')::int) as 정산건수
from legacy_settlements
where item = 'PND'
group by period_key, period_label
order by period_key;
